function hydrate(o){const cp=x=>JSON.parse(JSON.stringify(x)),s=Object.assign(cp(DEF),o),n=o.nt||{};
  s.tb=Object.assign(cp(DEF.tb),o.tb);s.gx=Object.assign(cp(DEF.gx),o.gx);
  s.nt=Object.assign(cp(DEF.nt),n);s.nt.pr=Object.assign(cp(DEF.nt.pr),n.pr);s.nt.every=Object.assign(cp(DEF.nt.every),n.every);
  s.nt.sch={};for(const k in DEF.nt.sch)s.nt.sch[k]=Object.assign({},DEF.nt.sch[k],(n.sch||{})[k]);
  if(!Array.isArray(s.nt.cu))s.nt.cu=[];if(!s.nt.fired||typeof s.nt.fired!=='object')s.nt.fired={};
  if(o.remOn!=null&&!o.nt){s.nt.every.on=o.remOn;s.nt.every.min=o.remMin||10}
  delete s.remOn;delete s.remMin;delete s.remNext;return s}
function loadState(){let o=rd(KEY);if(!o||typeof o!=='object')o=migrate();return hydrate(o)}
/* ترحيل بيانات النسخة القديمة (v.01) حتى لا يفقد المستخدم مفضلته */
function migrate(){const o={},fav=rd('fav'),cu=rd('cu'),bm=rd('bm'),tb=rd('tb'),loc=rd('loc'),st=rd('st'),g=k=>{try{return localStorage.getItem(k)}catch(e){return null}};
  if(Array.isArray(fav))o.my=fav.filter(t=>typeof t==='string').map(t=>({t}));
  if(Array.isArray(cu)){o.cu=[];o.my=o.my||[];cu.forEach(x=>{const id=IDS[x.c];if(!id||!x.t)return;
    if(id==='my'){const m=o.my.find(y=>y.t==x.t);if(m)m.n=x.n;else o.my.push({t:x.t,n:x.n})}else o.cu.push({c:id,t:x.t,n:x.n})})}
  if(bm&&bm.n)o.mq={s:bm.n,a:bm.a};if(tb&&typeof tb==='object')o.tb=tb;if(loc&&loc.a)o.loc=loc;
  if(+g('R'))o.R=+g('R');if(g('tm'))o.theme=g('tm');if(g('pm'))o.pm=g('pm');
  if(st){if(st.fz)o.fs=st.fz;if(st.wake!=null)o.wake=st.wake;if(st.auto!=null)o.auto=st.auto}
  return o}
