/* ---------- أنيميشن إضافي: تموّج سائل عند اللمس + احتفال إتمام الذكر ---------- */
const CK='<svg class="ckm" viewBox="0 0 24 24" width="26" height="26" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg>',CKS=CK.replace('class="ckm"','class="ckm s"');
