/* ---------- ٧) الأقسام والبطاقات ---------- */
let doneT=0,ENT=0;
V.cat=v=>{const c=BY[v.id],L=listOf(c),b=$('#body');head({title:c.name,color:c.color,bar:1,reset:1});ENT=!v.full;
  b.classList.toggle('lite',L.length>30);
  b.innerHTML=(c.note?`<details class="note"><summary>ملاحظات</summary><p>${esc(c.note)}</p></details>`:'')+
    (c.id==='my'?'<button class="row" data-a="add"><span>＋ إضافة ذكر جديد</span></button>':'')+
    (L.length?(L.length>40&&!v.full?L.slice(0,CH()).map(card).join(''):L.map(card).join('')):'<p class="em">اضغط ♡ على أي ذكر ليظهر هنا، أو أضف ذكرك الخاص.</p>');
  ENT=0;b.onclick=e=>catClick(e,c);if(L.length>40&&!v.full)chunkCards(b,L,CH(),v);doneT=L.length&&L.every(doneN)?v:0;bar()};
/* عرض القوائم الطويلة على دفعات حتى يفتح القسم فورًا حتى على الهواتف الضعيفة */
const CH=()=>S.weak?12:30;
function chunkCards(el,L,i,v){if(cv()!==v||i>=L.length)return;
  el.insertAdjacentHTML('beforeend',L.slice(i,i+CH()).map((it,k)=>card(it,i+k)).join(''));setTimeout(()=>chunkCards(el,L,i+CH(),v),S.weak?70:40)}
function card(it,i){const R=need(it),n=S.cnt[it.k]||0,g=gradeOf(it),f=S.my.some(x=>x.t==it.t),tx=S.tk?it.t:it.t.replace(TK,'');
  return`<article class="card glass${n>=R?' done':''}${ENT&&i<10?' ent':''}" data-i="${i}"${ENT&&i<10?` style="--k:${i}"`:''}>${it.h?`<p class="hd">${esc(it.h)}</p>`:''}<p class="t${tx.length>110?' s':tx.length<28?' b':''}">${esc(tx).replace(/\u06DD/g,'<span class="ayn">\u06DD</span>')}</p>${S.src&&(it.s||g)?`<p class="src">${g?`<b class="gd ${g[1]}">${g[0]}</b>`:''}${esc(it.s)}</p>`:''}<div class="f"><div class="ring" style="--p:${n/R*100}"><b>${n>=R?CKS:ar(n)}</b></div><span class="of">${lbl(R)}</span>${it.r?'<button class="mini" data-a="q">المصحف</button>':''}${it.custom?'<button class="mini bad" data-a="del">حذف</button>':''}<button class="fav${f?' on':''}" data-a="fav" aria-label="مفضلة">${f?'♥':'♡'}</button></div></article>`}
function catClick(e,c){const a=e.target.closest('[data-a]'),cd_=e.target.closest('.card'),act=a&&a.dataset.a;
  if(act==='add')return openAdd('my');
  if(!cd_)return;const it=listOf(c)[+cd_.dataset.i];if(!it)return;
  if(act==='fav'){const i=S.my.findIndex(x=>x.t==it.t);if(i>=0)S.my.splice(i,1);else S.my.push({t:it.t,n:it.n,s:it.s,r:it.r,h:it.h});sv();
    if(c.id==='my'){cd_.classList.add('out');setTimeout(refresh,280)}else{a.classList.toggle('on',i<0);a.textContent=i<0?'♥':'♡'}return}
  if(act==='del'){S.cu=S.cu.filter(x=>!(x.c==c.id&&x.t==it.t));c.items=c.items.filter(x=>x!==it);delete S.cnt[it.k];sv();refresh();return}
  if(act==='q'){go({t:'rd',s:it.r[0],a:it.r[1],e:it.r[2]});return}
  count(cd_,it)}
function count(cardEl,it){const R=need(it),n=(S.cnt[it.k]||0)+1;if(n>R)return;S.cnt[it.k]=n;sv();
  const r=$('.ring',cardEl);r.style.setProperty('--p',n/R*100);$('b',r).innerHTML=n>=R?CK:ar(n);r.classList.remove('pop');void r.offsetWidth;r.classList.add('pop');
  haptic(n>=R?[18,40,18]:8);
  if(n>=R){cardEl.classList.add('done');burst(r);if(S.auto){const x=cardEl.nextElementSibling;if(x&&x.classList.contains('card'))setTimeout(()=>x.scrollIntoView({behavior:S.weak?'auto':'smooth',block:'center'}),450)}}
  bar()}
function bar(){const v=cv();if(!v||v.t!=='cat')return;const L=listOf(BY[v.id]),d=L.filter(doneN).length;
  $('#bar i').style.width=(L.length?d/L.length*100:0)+'%';
  if(L.length&&d===L.length){if(doneT!==v){doneT=v;toast('تقبّل الله طاعتكم 🤲')}}else if(doneT===v)doneT=0}
$('#rs').onclick=()=>{const v=cv();if(!v)return;if(v.t==='tasbih')return tbReset();
  if(v.t==='cat'){listOf(BY[v.id]).forEach(it=>delete S.cnt[it.k]);doneT=0;sv();refresh();toast('تمت إعادة العدّ')}};

/* ---------- ٨) إضافة ذكر ---------- */
$('#ac').innerHTML=CATS.map(c=>`<option value="${c.id}">${c.name}</option>`).join('');
function openAdd(id){$('#ac').value=id||'my';$('#at').value='';$('#an').value=S.R;openOv('#add')}
$('#as0').onclick=()=>closeOv('#add');
$('#as1').onclick=()=>{const t=$('#at').value.trim(),id=$('#ac').value,n=Math.min(1000,Math.max(1,parseInt($('#an').value)||S.R));
  if(!t){$('#at').focus();return}
  if(id==='my'){S.my=S.my.filter(x=>x.t!=t);S.my.push({t,n})}
  else{S.cu=S.cu.filter(x=>!(x.c==id&&x.t==t));S.cu.push({c:id,t,n});const c=BY[id];c.items=c.items.filter(x=>!(x.custom&&x.t==t));c.items.push({t,n,s:'',r:null,h:'',k:id+'|c|'+t,custom:1})}
  flush();closeOv('#add');toast('تمت إضافة الذكر ✓');const v=cv();if(v&&v.t==='cat'&&v.id===id)refresh()};

/* ---------- ٩) الموقع والمواقيت والقبلة ---------- */
const CITIES=`القاهرة,30.04,31.24;الجيزة,30.01,31.21;الإسكندرية,31.20,29.92;الإسماعيلية,30.59,32.27;بورسعيد,31.27,32.30;السويس,29.97,32.55;المنصورة,31.04,31.38;طنطا,30.79,31.00;الزقازيق,30.59,31.50;دمياط,31.42,31.81;الفيوم,29.31,30.84;بني سويف,29.07,31.10;المنيا,28.11,30.75;أسيوط,27.18,31.18;سوهاج,26.56,31.70;الأقصر,25.69,32.64;أسوان,24.09,32.90;الغردقة,27.26,33.81;شرم الشيخ,27.91,34.33;مكة المكرمة,21.42,39.83;المدينة المنورة,24.47,39.61;الرياض,24.71,46.68;جدة,21.54,39.17;الدمام,26.43,50.10;الطائف,21.27,40.42;أبها,18.22,42.50;تبوك,28.38,36.57;دبي,25.20,55.27;أبوظبي,24.45,54.38;الشارقة,25.35,55.42;الدوحة,25.29,51.53;الكويت,29.38,47.99;المنامة,26.23,50.59;مسقط,23.59,58.41;صنعاء,15.35,44.21;عدن,12.79,45.02;بغداد,33.31,44.36;البصرة,30.51,47.78;الموصل,36.34,43.13;أربيل,36.19,44.01;دمشق,33.51,36.28;حلب,36.20,37.16;بيروت,33.89,35.50;عمّان,31.95,35.93;القدس,31.77,35.21;غزة,31.50,34.47;رام الله,31.90,35.20;طرابلس (ليبيا),32.89,13.19;بنغازي,32.12,20.09;تونس,36.81,10.18;الجزائر,36.75,3.06;وهران,35.70,-0.63;الدار البيضاء,33.57,-7.59;الرباط,34.02,-6.84;مراكش,31.63,-8.01;فاس,34.03,-5.00;الخرطوم,15.50,32.56;مقديشو,2.05,45.32;جيبوتي,11.59,43.15;نواكشوط,18.09,-15.98;إسطنبول,41.01,28.98;أنقرة,39.93,32.86;إزمير,38.42,27.14;طهران,35.69,51.39;كابول,34.53,69.17;كراتشي,24.86,67.01;لاهور,31.55,74.34;إسلام آباد,33.69,73.05;دلهي,28.61,77.21;مومباي,19.08,72.88;دكا,23.81,90.41;جاكرتا,-6.21,106.85;كوالالمبور,3.14,101.69;سنغافورة,1.35,103.82;لندن,51.51,-0.13;باريس,48.86,2.35;برلين,52.52,13.40;مدريد,40.42,-3.70;روما,41.90,12.50;أمستردام,52.37,4.90;بروكسل,50.85,4.35;ستوكهولم,59.33,18.07;موسكو,55.76,37.62;نيويورك,40.71,-74.01;واشنطن,38.91,-77.04;شيكاغو,41.88,-87.63;لوس أنجلوس,34.05,-118.24;تورنتو,43.65,-79.38;سيدني,-33.87,151.21;ملبورن,-37.81,144.96;جوهانسبرغ,-26.20,28.05;لاغوس,6.52,3.38;نيروبي,-1.29,36.82;أديس أبابا,9.03,38.75;داكار,14.72,-17.47`.split(';').map(s=>{const p=s.split(',');return{n:p[0],a:+p[1],o:+p[2]}});
const PM={mwl:[18,17,'رابطة العالم الإسلامي'],egy:[19.5,17.5,'الهيئة المصرية'],uq:[18.5,0,'أم القرى']};
const PN=['الفجر','الشروق','الظهر','العصر','المغرب','العشاء'];
const hm=x=>{if(isNaN(x))return'--';x=(x%24+24)%24;let h=Math.floor(x),m=Math.round((x-h)*60);if(m==60){h=(h+1)%24;m=0}return ar(h%12||12)+':'+ar2(m)+(h<12?' ص':' م')};
/* حساب المواقيت فلكيًا (بدون إنترنت) — يعيد ٦ أوقات بالساعات: الفجر، الشروق، الظهر، العصر، المغرب، العشاء */
function times(d=new Date()){const r=Math.PI/180,s=x=>Math.sin(x*r),c=x=>Math.cos(x*r),fx=(a,b)=>(a%b+b)%b,L=S.loc,la=L.a,
  jd=Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())/864e5+2440587.5-L.o/360,
  sp=t=>{const D=jd+t-2451545,g=fx(357.529+.98560028*D,360),q=fx(280.459+.98564736*D,360),Lg=fx(q+1.915*s(g)+.02*s(2*g),360),e=23.439-3.6e-7*D;
    return[Math.asin(s(e)*s(Lg))/r,q/15-fx(Math.atan2(c(e)*s(Lg),c(Lg))/r/15,24)]},
  md=t=>fx(12-sp(t)[1],24),
  at=(a,t,w)=>{const dc=sp(t)[0],h=Math.acos((-s(a)-s(dc)*s(la))/(c(dc)*c(la)))/r/15;return md(t)+(w?-h:h)},
  m=PM[S.pm]||PM.mwl,as=-Math.atan(1/(1+Math.tan(Math.abs(la-sp(13/24)[0])*r)))/r,mg=at(.833,18/24),o=-d.getTimezoneOffset()/60-L.o/15;
  return[at(m[0],5/24,1),at(.833,6/24,1),md(12/24),at(as,13/24),mg,m[1]?at(m[1],18/24):mg+1.5].map(x=>x+o)}
/* تحديد الموقع: تلقائي (GPS مع اسم المركز) أو يدوي (قائمة جاهزة / بحث عبر الإنترنت / إحداثيات) */
const setLoc=(a,o,n,src)=>{S.loc={a,o,n,src};S.locAt=Date.now();sv()};
function placeLabel(ad,dn){ad=ad||{};const u=[];
  [ad.village||ad.town||ad.city||ad.suburb||ad.hamlet,ad.county||ad.state_district,ad.state].filter(Boolean).forEach(x=>{if(!u.includes(x))u.push(x)});
  return(u.length?u.slice(0,2).join('، '):String(dn||'').split(',').slice(0,2).join('، ')).trim()}
async function reverseName(a,o){try{const r=await fetch('https://nominatim.openstreetmap.org/reverse?format=jsonv2&addressdetails=1&zoom=12&accept-language=ar&lat='+a+'&lon='+o);if(!r.ok)return'';const j=await r.json();return placeLabel(j.address,j.display_name)}catch(e){return''}}
async function placeSearch(q){const r=await fetch('https://nominatim.openstreetmap.org/search?format=jsonv2&addressdetails=1&limit=8&accept-language=ar&q='+encodeURIComponent(q));if(!r.ok)throw new Error('net');
  return(await r.json()).map(x=>({n:placeLabel(x.address,x.display_name),a:+x.lat,o:+x.lon}))}
function autoLocate(){return new Promise(res=>{if(!navigator.geolocation)return res(false);
  navigator.geolocation.getCurrentPosition(async p=>{const a=p.coords.latitude,o=p.coords.longitude,
      same=S.loc&&S.loc.src==='gps'&&S.loc.n&&S.loc.n!=='موقعي الحالي'&&Math.abs(S.loc.a-a)<.02&&Math.abs(S.loc.o-o)<.02;
    setLoc(a,o,same?S.loc.n:'موقعي الحالي','gps');res(true);
    if(!same){const n=await reverseName(a,o);if(n&&S.loc&&S.loc.src==='gps'&&S.loc.a===a){S.loc.n=n;sv();const e=$('#locn');if(e)e.textContent=n}}},
    ()=>res(false),{timeout:10000,maximumAge:3e5})})}
function needLoc(v,f){
  if(S.loc){f();if(S.locAuto&&S.loc.src==='gps'&&Date.now()-S.locAt>216e5)autoLocate().then(ok=>{if(ok&&cv()===v)f()});return}
  if(S.locAuto){$('#body').innerHTML='<p class="em">جارٍ تحديد موقعك تلقائيًا…</p>';
    autoLocate().then(ok=>{if(cv()!==v)return;ok?f():pickPlace(v,f,'تعذّر تحديد موقعك تلقائيًا (الإذن مرفوض أو غير متاح هنا). يمكنك إيقاف الموقع التلقائي واختيار موقعك يدويًا.')});return}
  pickPlace(v,f)}
function pickPlace(v,f,msg){clearInterval(ti);
  $('#body').innerHTML=`<div class="hero glass"><p class="lb" style="margin:0">اختر موقعك لحساب المواقيت والقبلة</p></div><p class="at" id="gpm" style="text-align:start">${esc(msg||'')}</p>`+
    (S.locAuto?`<button class="row pri" id="gps"><span>تحديد موقعي تلقائيًا (حتى المركز)</span></button><button class="row" id="gman"><span>إيقاف الموقع التلقائي واستخدام الموقع اليدوي</span></button>`:`<button class="row" id="gauto2"><span>تشغيل الموقع التلقائي</span></button>`)+
    `<input id="qs" type="text" placeholder="ابحث عن مدينتك في القائمة" autocomplete="off"><div id="ql">${CITIES.map((c,i)=>`<button class="sr" data-i="${i}"><span>${c.n}</span></button>`).join('')}</div><button class="row" id="osr"><span>بحث عن مركز أو قرية (يحتاج إنترنت)</span></button><div id="pres"></div><details class="note"><summary>إدخال إحداثيات يدويًا</summary><input class="inp" id="la" type="number" step="any" placeholder="خط العرض (مثال 30.04)"><input class="inp" id="lo" type="number" step="any" placeholder="خط الطول (مثال 31.24)"><button class="row" id="lsv"><span>حفظ الإحداثيات</span></button></details><p class="at">بحث الأماكن عبر OpenStreetMap — © مساهمو OpenStreetMap</p>`;
  const pick=(a,o,n)=>{setLoc(a,o,n,'manual');if(cv()===v){f();toast('تم اختيار: '+n)}},say=t=>{const m=$('#gpm');if(m)m.textContent=t};
  $('#qs').oninput=e=>{const q=NORM(e.target.value.trim());$$('#ql .sr').forEach(x=>x.hidden=!!q&&!NORM(CITIES[x.dataset.i].n).includes(q))};
  $('#ql').onclick=e=>{const x=e.target.closest('.sr');if(x){const c=CITIES[x.dataset.i];pick(c.a,c.o,c.n)}};
  $('#osr').onclick=async()=>{const q=$('#qs').value.trim();if(!q)return toast('اكتب اسم المركز أو القرية في خانة البحث أولًا');
    const box=$('#pres');box.innerHTML='<p class="at">جارٍ البحث…</p>';
    try{const R=await placeSearch(q);box.innerHTML=R.length?R.map((r,i)=>`<button class="sr" data-r="${i}"><span>${esc(r.n)}</span></button>`).join(''):'<p class="at">لا نتائج — جرّب اسمًا آخر.</p>';
      box.onclick=e=>{const x=e.target.closest('.sr');if(x){const r=R[+x.dataset.r];pick(r.a,r.o,r.n)}}}
    catch(e){box.innerHTML='<p class="at">تعذّر البحث — تأكد من الاتصال بالإنترنت.</p>'}};
  $('#lsv').onclick=()=>{const a=parseFloat($('#la').value),o=parseFloat($('#lo').value);
    if(isNaN(a)||isNaN(o)||Math.abs(a)>90||Math.abs(o)>180)return toast('أدخل إحداثيات صحيحة');pick(a,o,'موقع مخصص')};
  const g=$('#gps');if(g)g.onclick=()=>{say('جارٍ تحديد موقعك…');
    autoLocate().then(ok=>{if(cv()!==v)return;if(ok){f();toast('تم تحديد موقعك تلقائيًا')}else say('تعذّر تحديد الموقع تلقائيًا (الإذن مرفوض أو غير متاح هنا). يمكنك إيقاف الموقع التلقائي واستخدام اليدوي.')})};
  const gm=$('#gman');if(gm)gm.onclick=()=>{S.locAuto=0;sv();syncSet();pickPlace(v,f,'تم إيقاف الموقع التلقائي — اختر مدينتك أو مركزك.')};
  const ga=$('#gauto2');if(ga)ga.onclick=()=>{S.locAuto=1;sv();syncSet();pickPlace(v,f)}}
/* كتلة الموقع المشتركة بين المواقيت والقبلة (الاسم + أزرار التلقائي/اليدوي) */
const locBlock=()=>`<div class="row locrow"><span id="locn">${esc(S.loc.n||'موقعي')}</span><b>${S.loc.src==='gps'?'تلقائي':'يدوي'}</b></div><p class="at" id="locmsg" style="text-align:start"></p>`+
  (S.locAuto?`<button class="row" data-act="reloc"><span>تحديث موقعي تلقائيًا</span></button><button class="row" data-act="toman"><span>إيقاف الموقع التلقائي واستخدام الموقع اليدوي</span></button>`
    :`<button class="row" data-act="chg"><span>تغيير المدينة / المركز</span></button><button class="row" data-act="toauto"><span>تشغيل الموقع التلقائي</span></button>`);
function locClick(e,again){const a=e.target.closest('[data-act]');if(!a)return false;const k=a.dataset.act,v=cv(),msg=t=>{const m=$('#locmsg');if(m)m.textContent=t};
  if(k==='reloc'){msg('جارٍ التحديد…');autoLocate().then(ok=>{if(cv()!==v)return;if(ok){again();toast('تم تحديث موقعك')}else msg('تعذّر تحديد الموقع تلقائيًا. يمكنك إيقاف الموقع التلقائي واستخدام اليدوي.')})}
  else if(k==='toman'){S.locAuto=0;sv();syncSet();pickPlace(v,again,'تم إيقاف الموقع التلقائي — اختر مدينتك أو مركزك.')}
  else if(k==='chg')pickPlace(v,again);
  else if(k==='toauto'){S.locAuto=1;sv();syncSet();msg('جارٍ التحديد…');
    autoLocate().then(ok=>{if(cv()!==v)return;if(ok){again();toast('تم تشغيل الموقع التلقائي')}else pickPlace(v,again,'تعذّر تحديد الموقع تلقائيًا — يمكنك إيقاف الموقع التلقائي واستخدام اليدوي.')})}
  else return false;return true}
V.place=v=>{head({title:'تحديد الموقع',color:'#4db6ac'});pickPlace(v,()=>back())};
let ti=0,QB=0,okq=0;
function stopT(){clearInterval(ti);removeEventListener('deviceorientationabsolute',ev,true);removeEventListener('deviceorientation',ev,true)}
V.prayer=v=>{head({title:'مواقيت الصلاة',color:'#4db6ac'});needLoc(v,prayer)};
function prayer(){clearInterval(ti);const T=times();
  $('#body').innerHTML=`<div class="hero glass"><p class="lb" style="margin:0">الصلاة القادمة</p><b class="big" id="nm"></b><b class="big" id="cdn" style="font-size:34px"></b></div>`+
    T.map((x,i)=>`<div class="pn glass" data-i="${i}"><span>${PN[i]}</span><b>${hm(x)}</b></div>`).join('')+
    `<p class="lb">طريقة الحساب</p><div class="seg" id="pms">${Object.keys(PM).map(k=>`<button data-m="${k}" class="${k==S.pm?'on':''}">${PM[k][2]}</button>`).join('')}</div>`+locBlock()+`<p class="at">المواقيت بحسب توقيت جهازك.</p>`;
  const tick=()=>{const p=nextPrayer();if(!p||!$('#nm'))return;$('#nm').textContent=PN[p.i];$('#cdn').textContent='بعد '+cd(p.s);$$('.pn').forEach(e=>e.classList.toggle('nx',+e.dataset.i==p.i))};
  tick();ti=setInterval(tick,1000);
  $('#body').onclick=e=>{if(locClick(e,prayer))return;const b=e.target.closest('#pms button');if(b){S.pm=b.dataset.m;sv();prayer()}}}
const ev=e=>{const h=e.webkitCompassHeading!=null?e.webkitCompassHeading:e.absolute&&e.alpha!=null?360-e.alpha:null;if(h==null||!$('#dl'))return;
  $('#dl').style.transform=`rotate(${-h}deg)`;const df=Math.abs((QB-h+540)%360-180);
  $('#hd').textContent=df<4?'أنت الآن في اتجاه القبلة ✓':'أدر هاتفك حتى تصير الكعبة أعلى الدائرة';if(df<4&&!okq)haptic(40);okq=df<4};
