function tbDraw(){const b=$('#tbn');if(!b)return;const t=S.tb;b.style.setProperty('--p',t.tg?t.n/t.tg*100:0);$('#tbc').textContent=ar(t.n);$('#lp').textContent=ar(t.lap);$('#tt').textContent=ar(t.tot)}
