/* ---------- ١١) المصحف (نظام صفحات + قراءة بدون إنترنت) ---------- */
const QU='https://cdn.jsdelivr.net/npm/quran-json@3.1.2/dist/chapters/',QC={},BQ='بِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ';
const AT='نص المصحف: موسوعة القرآن الكريم (quranenc.com) عبر quran-json، رخصة CC BY-SA 4.0';
/* كل سورة تُحفظ في IndexedDB بعد أول تحميل لتُقرأ بدون إنترنت.
   وإن وُجد ملف quran.js (متغيّر QURAN = مصفوفة نصوص الآيات لكل سورة) يُستخدم مباشرة بلا أي تحميل. */
let QDB=null,QDONE=!!window.QURAN,QSTAT=window.QURAN?'✓ جاهز':'غير محمّل',dlBusy=0;
const qdb=()=>QDB||(QDB=new Promise((res,rej)=>{try{const r=indexedDB.open('adhkar-quran',1);r.onupgradeneeded=()=>r.result.createObjectStore('c');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)}catch(e){rej(e)}}));
const idb=(mode,fn)=>qdb().then(db=>new Promise((res,rej)=>{const t=db.transaction('c',mode),q=fn(t.objectStore('c'));t.oncomplete=()=>res(q&&q.result);t.onerror=()=>rej(t.error)}));
const qGetC=n=>idb('readonly',s=>s.get(n)).catch(()=>null),qPutC=(n,v)=>idb('readwrite',s=>s.put(v,n)).catch(()=>{}),qCount=()=>idb('readonly',s=>s.count()).catch(()=>0);
async function qFetch(n){const u=QU+n+'.json';try{return await window.qImp(u)}catch(e){return await(await fetch(u)).json()}}
async function qget(n){if(window.QURAN&&QURAN[n-1])return QURAN[n-1];if(QC[n])return QC[n];
  let t=await qGetC(n);if(!t){const d=await qFetch(n);t=d.verses.map(v=>v.text);qPutC(n,t)}return QC[n]=t}
function qShow(n,busy){QDONE=n>=114;QSTAT=QDONE?'✓ جاهز':n||busy?ar(n)+'/١١٤':'غير محمّل';$$('[data-btn=qdl] b,#dlp').forEach(e=>e.textContent=QSTAT)}
async function dlQuran(){if(QDONE)return toast('المصحف متاح بدون إنترنت ✓');if(dlBusy)return;dlBusy=1;toast('بدأ تحميل المصحف…');
  try{const todo=[];let n=0;for(let i=1;i<=114;i++){if(await qGetC(i))n++;else todo.push(i)}qShow(n,1);
    const work=async()=>{while(todo.length){const i=todo.shift(),d=await qFetch(i),t=d.verses.map(v=>v.text);await qPutC(i,t);QC[i]=t;qShow(++n,1)}};
    await Promise.all([work(),work(),work()]);qShow(114);toast('تم تحميل المصحف — يعمل الآن بدون إنترنت ✓')}
  catch(e){qCount().then(n=>qShow(n));toast('تعذّر التحميل — تأكد من الإنترنت وأعد المحاولة')}dlBusy=0}
qCount().then(n=>qShow(window.QURAN?114:n));

V.mqi=()=>{head({title:'المصحف',sub:'١١٤ سورة',color:'#b99468'});
  const row=(k,l)=>S[k]?`<button class="row" data-go="${k}"><span>${l}</span><b>${SN[S[k].s-1]} · ${ar(S[k].a)}</b></button>`:'';
  $('#body').innerHTML=`<button class="row" data-dl="1"><span>${QDONE?'✓ المصحف متاح بدون إنترنت':'تحميل المصحف للقراءة بدون إنترنت'}</span><b id="dlp">${QDONE?'':QSTAT}</b></button>`+row('mq','متابعة القراءة')+row('mk','العلامة المحفوظة')+
    `<input id="qs" type="text" placeholder="ابحث باسم السورة أو رقمها" autocomplete="off" enterkeyhint="search"><div id="ql">${SN.map((s,i)=>`<button class="sr" data-n="${i+1}"><i>${ar(i+1)}</i><span>${s}</span><small>${ar(SC[i])}${SC[i]<11?' آيات':' آية'}</small></button>`).join('')}</div><p class="at">${AT}</p>`;
  $('#qs').oninput=e=>{const q=NORM(e.target.value.trim());$$('.sr').forEach(b=>{b.hidden=!!q&&!(NORM(SN[b.dataset.n-1]).includes(q)||b.dataset.n==q)})};
  $('#body').onclick=e=>{const g=e.target.closest('[data-go]'),b=e.target.closest('.sr');
    if(e.target.closest('[data-dl]'))dlQuran();
    else if(g){const m=S[g.dataset.go];go({t:'rd',s:m.s,a:m.a})}else if(b)go({t:'rd',s:+b.dataset.n,a:1})}};
const RD={};
V.rd=async v=>{head({title:SN[v.s-1],sub:'جارٍ التحميل…',color:'#b99468',nos:1});
  $('#body').innerHTML='<div class="rd"><div class="pgv"><div class="pg"><p class="em">جارٍ تحميل السورة…</p></div></div></div>';
  try{const d=await qget(v.s);if(cv()!==v)return;startRd(d,v)}
  catch(e){if(cv()!==v)return;$('#body').innerHTML='<p class="em">تعذّر تحميل نص السورة. حمّل المصحف مرة واحدة وأنت متصل بالإنترنت ليعمل بعدها بدون إنترنت.</p><button class="row pri" id="rt"><span>إعادة المحاولة</span></button><button class="row" id="rd2"><span>تحميل المصحف كاملًا</span></button>';
    $('#rt').onclick=()=>V.rd(v);$('#rd2').onclick=()=>dlQuran()}};
function startRd(d,v){const s=v.s,blocks=[`<div class="sh">سورة ${SN[s-1]}</div>`],ids=[0];
  if(s!=1&&s!=9){blocks.push(`<p class="bsm">${BQ}</p>`);ids.push(0)}
  d.forEach((t,i)=>{blocks.push(`<p class="vs" data-a="${i+1}">${esc(t)} <span class="an">${ar(i+1)}</span></p>`);ids.push(i+1)});
  $('#body').innerHTML='<div class="rd"><div class="pgv" id="pgv"></div><div class="pf"><button class="mini" id="pp">السابقة</button><input type="range" id="pr" min="1" max="1" value="1" aria-label="الصفحة"><button class="mini" id="pnx">التالية</button></div></div>';
  /* التقسيم إلى صفحات: نقيس ارتفاع كل كتلة ثم نملأ الصفحة حتى يمتلئ ارتفاعها */
  const pgv=$('#pgv'),H=pgv.clientHeight-28,m=document.createElement('div');m.className='pg meas';m.style.width=pgv.clientWidth+'px';m.innerHTML=blocks.join('');pgv.append(m);
  const hs=[...m.children].map(c=>c.getBoundingClientRect().height),pages=[];let cur=[],h=0;
  hs.forEach((x,i)=>{if(cur.length&&h+x>H){pages.push(cur);cur=[];h=0}cur.push(i);h+=x});if(cur.length)pages.push(cur);m.remove();
  Object.assign(RD,{s,blocks,ids,pages,i:0,v,w:innerWidth,hh:innerHeight});
  const a=v.a||1;let pi=pages.findIndex(p=>p.some(j=>ids[j]===a));if(pi<0)pi=a>1?pages.length-1:0;
  $('#pr').max=pages.length;$('#pp').onclick=()=>step(-1);$('#pnx').onclick=()=>step(1);$('#pr').oninput=e=>turn(+e.target.value-1,0);
  let x0=0,y0=0;pgv.addEventListener('touchstart',e=>{x0=e.touches[0].clientX;y0=e.touches[0].clientY},{passive:true});
  pgv.addEventListener('touchend',e=>{const t=e.changedTouches[0],dx=t.clientX-x0,dy=t.clientY-y0;if(Math.abs(dx)>60&&Math.abs(dx)>Math.abs(dy)*1.5)step(dx>0?1:-1)},{passive:true});
  turn(pi,0)}
function turn(i,dir){const{pages,blocks,ids,s,v}=RD;i=Math.max(0,Math.min(pages.length-1,i));RD.i=i;
  const hl=v.a&&v.e?[v.a,v.e]:null,mkd=S.mk&&S.mk.s==s?S.mk.a:0;
  const html=pages[i].map(j=>{let b=blocks[j];const id=ids[j];
    if(id){if(hl&&id>=hl[0]&&id<=hl[1])b=b.replace('class="vs"','class="vs hl"');if(id===mkd)b=b.replace('class="vs','class="vs mk')}return b}).join('');
  const pg=document.createElement('div');pg.className='pg'+(dir>0?' fwd':dir<0?' bck':'');pg.innerHTML=html;$('#pgv').replaceChildren(pg);
  $('#pr').value=i+1;$('#vs').textContent='صفحة '+ar(i+1)+' من '+ar(pages.length);
  S.mq={s,a:pages[i].map(j=>ids[j]).find(Boolean)||1};sv();
  $('#pp').textContent=i==0&&s>1?'السورة السابقة':'السابقة';$('#pnx').textContent=i==pages.length-1&&s<114?'السورة التالية':'التالية'}
function step(d){const{pages,i,s}=RD;if(i+d>=0&&i+d<pages.length)return turn(i+d,d);
  const ns=s+d;if(ns<1||ns>114)return;const v={t:'rd',s:ns,a:d>0?1:99999};nav[nav.length-1]=v;V.rd(v)}
$('#body').addEventListener('click',e=>{const p=e.target.closest('.vs'),v=cv();if(!p||!v||v.t!=='rd')return;
  const a=+p.dataset.a;$$('.vs.mk').forEach(x=>x.classList.remove('mk'));
  if(S.mk&&S.mk.s===RD.s&&S.mk.a===a){S.mk=null;toast('أُزيلت العلامة')}else{S.mk={s:RD.s,a};p.classList.add('mk');toast('تم حفظ العلامة: '+SN[RD.s-1]+' · '+ar(a))}sv()});
let rzT;addEventListener('resize',()=>{const v=cv();if(!v||v.t!=='rd'||!RD.pages)return;
  if(Math.abs(innerWidth-RD.w)<40&&Math.abs(innerHeight-RD.hh)<150)return;clearTimeout(rzT);rzT=setTimeout(refresh,250)});

/* ---------- ١٢) التنبيهات ---------- */
const PRN=[['fajr','الفجر',0],['dhuhr','الظهر',2],['asr','العصر',3],['maghrib','المغرب',4],['isha','العشاء',5]];
const SCH=[['morning','أذكار الصباح','morning'],['evening','أذكار المساء','evening'],['sleep','أذكار النوم','sleep'],['jumua','يوم الجمعة','']];
const gp=(o,p)=>p.split('.').reduce((a,k)=>a&&a[k],o),spth=(o,p,v)=>{const a=p.split('.'),l=a.pop();a.reduce((x,k)=>x[k],o)[l]=v};
const randomDhikr=()=>{const it=POOL[Math.floor(Math.random()*POOL.length)];return S.tk?it.t:it.t.replace(TK,'')};
let bnTarget=null;
/* إظهار تنبيه: شريط داخل التطبيق + إشعار النظام (إن سمح به المتصفح) + اهتزاز */
function notify(title,body,target){bnTarget=target;
  $('#bt').innerHTML=`<b>${esc(title)}</b><br>${esc(body)}`;$('#bo').hidden=!target;$('#bn').classList.add('on');
  clearTimeout(notify.h);notify.h=setTimeout(()=>$('#bn').classList.remove('on'),20000);haptic([20,60,20]);
  if('Notification' in window&&Notification.permission==='granted'){try{new Notification(title,{body,tag:'adhkar-'+title,lang:'ar',dir:'rtl'})}catch(e){}}}
$('#bx').onclick=()=>$('#bn').classList.remove('on');
$('#bo').onclick=()=>{$('#bn').classList.remove('on');if(bnTarget)go({t:'cat',id:bnTarget})};
/* المجدوِل: يفحص كل ٥ ثوانٍ ما حان موعده (مرة واحدة في اليوم لكل تنبيه) */
function checkNt(now=new Date()){const n=S.nt,dk=todayKey(now),mn=now.getHours()*60+now.getMinutes(),ms=now.getTime();let dirty=0;
  const once=(key,due,fn)=>{if(due&&n.fired[key]!==dk){n.fired[key]=dk;dirty=1;fn()}};
  const at=s=>{const[h,m]=String(s).split(':').map(Number);return h*60+m};
  SCH.forEach(([k,l,cat])=>{const s=n.sch[k];if(!s.on)return;const t=at(s.t);
    once('sch.'+k,mn>=t&&mn<t+3&&(k!=='jumua'||now.getDay()===5),()=>k==='jumua'?notify('يوم الجمعة','اقرأ سورة الكهف وأكثر من الصلاة على النبي ﷺ',''):notify(l,'حان وقت '+l,cat))});
  if(S.loc&&PRN.some(([k])=>n.pr[k])){const T=times(now);
    PRN.forEach(([k,l,i])=>{if(!n.pr[k])return;const t=Math.floor(T[i]*60);if(isNaN(t))return;once('pr.'+k,mn>=t&&mn<t+3,()=>notify('حان وقت صلاة '+l,'حيّ على الصلاة',''))})}
  const ev=n.every;if(ev.on){if(!ev.next){ev.next=ms+ev.min*6e4;dirty=1}else if(ms>=ev.next){ev.next=ms+ev.min*6e4;dirty=1;notify('تذكير بالذكر',randomDhikr(),'')}}
  n.cu.forEach(c=>{if(!c.on)return;
    if(c.ty==='e'){if(!c.next){c.next=ms+c.min*6e4;dirty=1}else if(ms>=c.next){c.next=ms+c.min*6e4;dirty=1;notify('تنبيه',c.x,'')}}
    else once('cu.'+c.id,mn>=at(c.t)&&mn<at(c.t)+3,()=>notify('تنبيه',c.x,''))});
  if(dirty)sv()}
/* صفحة التحكم في التنبيهات */
V.notif=()=>{head({title:'التنبيهات',color:'#ec7272'});drawNt();const b=$('#body');b.onclick=ntClick;
  b.onchange=e=>{const t=e.target;
    if(t.dataset.t){spth(S,'nt.'+t.dataset.t,t.value||'08:00');sv()}
    else if(t.dataset.m){const v=Math.max(1,Math.min(1440,Math.round(+t.value)||0));if(v){S.nt.every.min=v;S.nt.every.next=S.nt.every.on?Date.now()+v*6e4:0;sv();drawNt()}}}};
function drawNt(){const n=S.nt,P='Notification' in window?{granted:'مسموح',denied:'ممنوع من المتصفح',default:'اضغط للسماح'}[Notification.permission]:'غير مدعوم هنا';
  const sw=(k,l)=>`<button class="row" data-sw="${k}"><span>${l}</span><i class="sw${gp(n,k)?' on':''}"></i></button>`;
  const note=t=>`<p class="at" style="text-align:start">${t}</p>`;
  $('#body').innerHTML=
   `<details class="note"><summary>كيف تعمل التنبيهات؟</summary><p>يظهر التنبيه داخل التطبيق، وكإشعار نظام إن سمحت به. التنبيهات تعمل أثناء فتح التطبيق فقط؛ المتصفحات لا تسمح بجدولة إشعارات والتطبيق مغلق. على الآيفون أضف التطبيق إلى الشاشة الرئيسية لأفضل نتيجة.</p></details>`+
   `<button class="row" data-act="perm"><span>إشعارات النظام</span><b>${P}</b></button>`+
   `<h3 class="sh3">الأذكار المجدولة</h3>`+SCH.map(([k,l])=>`<div class="row nr"><span>${l}</span><input type="time" data-t="sch.${k}.t" value="${n.sch[k].t}"><button class="swb" data-sw="sch.${k}.on" aria-label="${l}"><i class="sw${n.sch[k].on?' on':''}"></i></button></div>`).join('')+
   `<h3 class="sh3">أوقات الصلاة</h3>`+note(S.loc?`بحسب ${esc(S.loc.n||'موقعك')} — لتغيير المدينة افتح مواقيت الصلاة.`:'اختر مدينتك أولًا من صفحة مواقيت الصلاة.')+PRN.map(([k,l])=>sw('pr.'+k,'عند أذان '+l)).join('')+
   `<h3 class="sh3">تذكير دوري</h3>`+sw('every.on','ذكر عشوائي كل '+ar(n.every.min)+' دقيقة')+`<div class="seg">${[5,10,15,30,60].map(m=>`<button data-m="${m}" class="${m==n.every.min?'on':''}">${ar(m)}</button>`).join('')}</div><input class="inp" type="number" data-m="1" min="1" max="1440" inputmode="numeric" placeholder="أو اكتب عدد الدقائق">`+
   `<h3 class="sh3">تنبيهاتك الخاصة</h3>`+(n.cu.length?n.cu.map((c,i)=>`<div class="row nr"><span>${esc(c.x)}<small class="sbt">${c.ty==='e'?'كل '+ar(c.min)+' دقيقة':'يوميًا '+c.t}</small></span><button class="mini bad" data-del="${i}">حذف</button><button class="swb" data-sw="cu.${i}.on"><i class="sw${c.on?' on':''}"></i></button></div>`).join(''):note('لا توجد تنبيهات خاصة بعد.'))+
   `<button class="row" data-act="nadd"><span>＋ إضافة تنبيه</span></button><button class="row" data-act="test"><span>تجربة تنبيه الآن</span></button>`}
function askPerm(){if('Notification' in window&&Notification.permission==='default')try{Notification.requestPermission().then(()=>{if(cv()&&cv().t==='notif')drawNt()})}catch(x){}}
function ntClick(e){const sw=e.target.closest('[data-sw]'),a=e.target.closest('[data-act]'),del=e.target.closest('[data-del]'),sg=e.target.closest('.seg button');
  if(sw){const k=sw.dataset.sw,v=gp(S.nt,k)?0:1;spth(S.nt,k,v);
    if(k==='every.on')S.nt.every.next=v?Date.now()+S.nt.every.min*6e4:0;
    const m=/^cu\.(\d+)\.on$/.exec(k);if(m&&v){const c=S.nt.cu[+m[1]];if(c.ty==='e')c.next=Date.now()+c.min*6e4}
    if(v)askPerm();sv();drawNt();return}
  if(sg){S.nt.every.min=+sg.dataset.m;S.nt.every.next=S.nt.every.on?Date.now()+S.nt.every.min*6e4:0;sv();drawNt();return}
  if(del){S.nt.cu.splice(+del.dataset.del,1);sv();drawNt();return}
  if(a){const k=a.dataset.act;
    if(k==='perm'){if(!('Notification' in window))return toast('إشعارات النظام غير مدعومة هنا — سيظهر التنبيه داخل التطبيق');Notification.requestPermission().then(drawNt).catch(()=>{})}
    if(k==='test')notify('تجربة التنبيه',randomDhikr(),'morning');
    if(k==='nadd'){$('#nx').value='';$('#nty').value='t';ntType();openOv('#nadd')}}}
const ntType=()=>{const e=$('#nty').value==='e';$('#ntt').hidden=e;$('#nte').hidden=!e};
$('#nty').onchange=ntType;$('#ns0').onclick=()=>closeOv('#nadd');
$('#ns1').onclick=()=>{const x=$('#nx').value.trim(),ty=$('#nty').value,t=$('#ntv').value||'08:00',min=Math.max(1,Math.min(1440,Math.round(+$('#nmv').value)||30));
  if(!x){$('#nx').focus();return}
  S.nt.cu.push({id:Date.now(),x,ty,t,min,on:1,next:ty==='e'?Date.now()+min*6e4:0});askPerm();flush();closeOv('#nadd');toast('تمت إضافة التنبيه ✓');if(cv()&&cv().t==='notif')drawNt()};

/* ---------- النسخ الاحتياطي (ملف / نص) ---------- */
const backupJSON=()=>{const{guser,gcid,gmt,gat,gauto,fb,fbk,fbp,...r}=S;return JSON.stringify({app:'adhkar',v:3,at:Date.now(),data:r})};
function importBackup(txt,keep){let o;try{o=JSON.parse(txt)}catch(e){return toast('النص غير صالح — تأكد من نسخه كاملًا')}
  const d=o&&o.app==='adhkar'?o.data:o;if(!d||typeof d!=='object'||!('my' in d||'nt' in d||'cnt' in d))return toast('هذه ليست نسخة احتياطية للأذكار');
  const k={guser:S.guser,gcid:S.gcid,gauto:S.gauto,gmt:S.gmt,gat:S.gat,fb:S.fb,fbk:S.fbk,fbp:S.fbp};S=hydrate(d);Object.assign(S,k,keep||{});wiped=0;flush(1);toast('تمت الاستعادة ✓');setTimeout(()=>location.reload(),600)}
function openBackup(){$('#impt').value=backupJSON();closeOv('#set');openOv('#imp')}
async function exportFile(){const json=$('#impt').value||backupJSON(),name='adhkar-backup-'+todayKey()+'.json';
  try{const f=new File([json],name,{type:'application/json'});if(navigator.canShare&&navigator.canShare({files:[f]})){await navigator.share({files:[f],title:'نسخة احتياطية — الأذكار'});return}}catch(e){if(e&&e.name==='AbortError')return}
  try{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([json],{type:'application/json'}));a.download=name;document.body.append(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},800);toast('تم تنزيل الملف ✓')}
  catch(e){toast('تعذّر التنزيل — انسخ النص بدلًا من ذلك')}}
$('#ib1').onclick=exportFile;
$('#ib2').onclick=()=>{const t=$('#impt');t.select();let ok=0;try{ok=navigator.clipboard&&navigator.clipboard.writeText(t.value)}catch(e){}if(!ok)try{document.execCommand('copy')}catch(e){}toast('تم نسخ النص ✓')};
$('#ib3').onclick=()=>$('#impf').click();
$('#impf').onchange=e=>{const f=e.target.files[0];if(f)f.text().then(t=>{$('#impt').value=t;toast('تم تحميل الملف — اضغط «استعادة من النص»')})};
$('#ib4').onclick=()=>importBackup($('#impt').value);
/* ---------- حساب جوجل: تسجيل دخول عادي (هوية فقط) + مزامنة التغييرات سحابيًا عبر Firebase ----------
   الدخول: Google Identity Services (اسم + بريد + صورة فقط، بدون أي صلاحية على Drive).
   المزامنة: Firestore REST (مستند خاص بكل مستخدم) — اختيارية وتحتاج إعداد Firebase مرة واحدة. */
let GDEB=20000,fbTok=null,fbExp=0,gisId='';
function gcid(){return GOOGLE_CLIENT_ID||S.gcid||''}
const fbReady=()=>!!(S.fbk&&S.fbp);
const gHead=t=>({Authorization:'Bearer '+t});
const gScript=()=>new Promise((res,rej)=>{if(window.google&&google.accounts&&google.accounts.id)return res();const s=document.createElement('script');s.src='https://accounts.google.com/gsi/client';s.async=1;s.onload=res;s.onerror=()=>rej(new Error('load'));document.head.append(s)});
const jwt=t=>{try{const b=t.split('.')[1].replace(/-/g,'+').replace(/_/g,'/');return JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(b),c=>c.charCodeAt(0))))}catch(e){return null}};
async function gisInit(){await gScript();if(gisId===gcid())return;
  google.accounts.id.initialize({client_id:gcid(),callback:onCred,auto_select:false,cancel_on_tap_outside:true});gisId=gcid()}
/* زر «تسجيل الدخول بجوجل» الرسمي */
function renderGBtn(){const el=$('#gbtn');if(!el)return;
  gisInit().then(()=>{if($('#gbtn')!==el)return;el.innerHTML='';google.accounts.id.renderButton(el,{type:'standard',theme:'outline',size:'large',shape:'pill',text:'signin_with',locale:'ar',width:Math.min(300,el.clientWidth||300)})})
   .catch(()=>{el.innerHTML='<button class="row gbtn" data-btn="gretry"><span>تعذّر تحميل زر جوجل (تأكد من الإنترنت) — اضغط للمحاولة</span></button>'})}
async function onCred(r){const p=jwt(r&&r.credential);if(!p)return toast('تعذّر قراءة بيانات الدخول');
  S.guser={name:p.name||p.email||'حسابي',email:p.email||'',pic:p.picture||'',sub:p.sub||''};S.gauto=1;sv();syncSet();toast('أهلًا '+S.guser.name+' ✓');
  if(!fbReady())return;
  try{await fbSignIn(r.credential);const d=await fbGet();
    if(d&&d.data&&await ask('وجدنا نسخة محفوظة في حسابك بتاريخ '+new Date(d.time).toLocaleDateString('ar-EG')+'. هل تريد استعادتها الآن؟','استعادتها','لا، ابدأ بما عندي'))return importBackup(d.data,{gmt:d.time,gat:Date.now()});
    await fbSave(true)}
  catch(e){toast('تم الدخول، لكن تعذّر ربط المزامنة — راجع إعدادات Firebase')}}
async function fbSignIn(cred){const o=location.origin;
  const r=await fetch('https://identitytoolkit.googleapis.com/v1/accounts:signInWithIdp?key='+S.fbk,{method:'POST',headers:{'Content-Type':'application/json'},
    body:JSON.stringify({postBody:'id_token='+cred+'&providerId=google.com',requestUri:o&&o!=='null'?o:'http://localhost',returnIdToken:true,returnSecureToken:true})});
  if(!r.ok)throw new Error('fbauth');const j=await r.json();fbTok=j.idToken;fbExp=Date.now()+((+j.expiresIn||3600)-60)*1000;S.fb={uid:j.localId,rt:j.refreshToken};sv()}
async function fbAuth(){if(fbTok&&Date.now()<fbExp)return fbTok;if(!S.fb||!S.fb.rt)throw new Error('nologin');
  const r=await fetch('https://securetoken.googleapis.com/v1/token?key='+S.fbk,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'grant_type=refresh_token&refresh_token='+encodeURIComponent(S.fb.rt)});
  if(!r.ok)throw new Error('fbrefresh');const j=await r.json();fbTok=j.id_token;fbExp=Date.now()+((+j.expires_in||3600)-60)*1000;S.fb={uid:j.user_id||S.fb.uid,rt:j.refresh_token||S.fb.rt};sv();return fbTok}
const fbDoc=()=>'https://firestore.googleapis.com/v1/projects/'+S.fbp+'/databases/(default)/documents/adhkar/'+S.fb.uid;
async function fbGet(){const t=await fbAuth(),r=await fetch(fbDoc(),{headers:gHead(t)});if(r.status===404)return null;if(!r.ok)throw new Error('fbget');
  const j=await r.json();return{data:(j.fields&&j.fields.data&&j.fields.data.stringValue)||'',time:Date.parse(j.updateTime)||0}}
async function fbSave(quiet){const t=await fbAuth(),r=await fetch(fbDoc()+'?updateMask.fieldPaths=data&updateMask.fieldPaths=at',{method:'PATCH',headers:{...gHead(t),'Content-Type':'application/json'},
    body:JSON.stringify({fields:{data:{stringValue:backupJSON()},at:{integerValue:String(Date.now())}}})});
  if(!r.ok)throw new Error('fbsave');const j=await r.json();S.gmt=Date.parse(j.updateTime)||Date.now();S.gat=Date.now();flush(1);syncSet();if(!quiet)toast('تم حفظ تغييراتك في حسابك ✓')}
async function fbLoad(){const d=await fbGet();if(!d||!d.data)return toast('لا توجد نسخة محفوظة في حسابك بعد');importBackup(d.data,{gmt:d.time,gat:Date.now()})}
/* مزامنة تلقائية بعد كل تغيير؛ وإن كانت هناك نسخة أحدث من جهاز آخر نسألك قبل الاستبدال */
function gAuto(){if(!S.gauto||!S.guser||!S.fb||!fbReady())return;clearTimeout(gT);gT=setTimeout(fbSync,GDEB)}
async function fbSync(){try{const d=await fbGet();
  if(d&&S.gmt&&d.time>S.gmt+1000&&await ask('توجد نسخة أحدث في حسابك (من جهاز آخر). هل تريد استعادتها بدل حفظ تغييراتك؟','استعادتها','حفظ تغييراتي'))return importBackup(d.data,{gmt:d.time,gat:Date.now()});
  await fbSave(true)}catch(e){}}
function fbBoot(){if(!S.gauto||!S.guser||!S.fb||!fbReady())return;
  fbGet().then(d=>{if(d&&d.data&&S.gmt&&d.time>S.gmt+1000)return ask('وجدنا تغييرات أحدث في حسابك. هل تريد استعادتها؟','استعادتها','لاحقًا').then(y=>{if(y)importBackup(d.data,{gmt:d.time,gat:Date.now()})})}).catch(()=>{})}
function gSignOut(){try{google.accounts.id.disableAutoSelect()}catch(e){}fbTok=null;fbExp=0;S.guser=null;S.fb=null;S.gauto=0;S.gmt=0;sv();syncSet();toast('تم تسجيل الخروج')}
function gRun(fn){if(!fbReady()||!S.fb)return openGset();
  fn().catch(e=>toast(e&&e.message==='fbrefresh'?'انتهت صلاحية الدخول — سجّل الدخول من جديد':'تعذّر الاتصال بحسابك — تأكد من الإنترنت وأعد المحاولة'))}
/* بطاقة الحساب في الإعدادات (تُعاد كتابتها فقط عند تغيّر حالتها حتى لا يومض زر جوجل) */
function gcardHTML(){const u=S.guser,ic='<b class="gl">G</b>',sync=fbReady();
  if(!gcid())return`<button class="row" data-btn="gset"><span>${ic}ربط حساب جوجل لحفظ تغييراتك</span><b>إعداد</b></button>`;
  if(!u)return`<div id="gbtn" class="gbw"></div>`+(sync?'':`<p class="at" style="text-align:start">الدخول يعمل الآن. لحفظ بياناتك سحابيًا في حسابك أضف إعدادات Firebase (اختياري).</p>`)+`<button class="row" data-btn="gset"><span>إعدادات الربط</span></button>`;
  return`<div class="row"><span>${u.pic?`<img class="av" src="${esc(u.pic)}" alt="" referrerpolicy="no-referrer">`:`<i class="av">${esc([...u.name][0]||'?')}</i>`}${esc(u.name)}<small class="sbt">${esc(u.email)}</small></span><button class="mini bad" data-btn="gout">خروج</button></div>`+
    (sync&&S.fb?`<button class="row" data-sw="gauto"><span>مزامنة تلقائية للتغييرات</span><i class="sw${S.gauto?' on':''}"></i></button><button class="row" data-btn="gsave"><span>حفظ نسخة الآن</span><b>${S.gat?new Date(S.gat).toLocaleDateString('ar-EG'):''}</b></button><button class="row" data-btn="gload"><span>استعادة من حسابي</span></button>`
      :`<p class="at" style="text-align:start">أنت مسجّل الدخول. لحفظ تغييراتك سحابيًا في حسابك أضف إعدادات Firebase (اختياري).</p><button class="row" data-btn="gset"><span>إعدادات المزامنة</span></button>`)}
function renderGCard(){const gc=$('#gcard');if(!gc)return;const sig=[gcid(),!!S.guser,S.gauto,S.gat,fbReady(),!!S.fb].join('|');
  if(gc.dataset.sig===sig)return;gc.dataset.sig=sig;gc.innerHTML=gcardHTML();if($('#gbtn'))renderGBtn()}
function openGset(){closeOv('#set');$('#gcin').value=gcid();$('#fbk').value=S.fbk||'';$('#fbp').value=S.fbp||'';openOv('#gcs')}
$('#gcs0').onclick=()=>closeOv('#gcs');
$('#gcs1').onclick=()=>{const c=$('#gcin').value.trim(),k=$('#fbk').value.trim(),p=$('#fbp').value.trim();
  if(c&&!/^[\w.-]+\.apps\.googleusercontent\.com$/.test(c))return toast('صيغة Client ID غير صحيحة — يجب أن ينتهي بـ apps.googleusercontent.com');
  if(p&&!/^[a-z0-9-]+$/i.test(p))return toast('Project ID غير صحيح');
  S.gcid=c;S.fbk=k;S.fbp=p;gisId='';sv();closeOv('#gcs');const g=$('#gcard');if(g)delete g.dataset.sig;syncSet();toast('تم حفظ الإعدادات ✓')};
/* نافذة تأكيد عامة تعيد وعدًا (true/false) */
let askRes=null;
function ask(msg,ok,no){return new Promise(res=>{askRes=res;$('#gqm').textContent=msg;$('#gq1 span').textContent=ok||'موافق';$('#gq0 span').textContent=no||'إلغاء';openOv('#gq')})}
const askDone=v=>{closeOv('#gq');if(askRes){askRes(v);askRes=null}};
$('#gq1').onclick=()=>askDone(true);$('#gq0').onclick=()=>askDone(false);$('#gq .scrim').onclick=()=>askDone(false);

/* ---------- ١٣) التشغيل ---------- */
buildSet();applyS();syncSet();renderHome();tabSync();applyIcon();tiltSet(S.gx.tilt);
let sn=0;setInterval(()=>{if(S.weak&&++sn%8)return;strip()},1000);setInterval(checkNt,5000);setTimeout(fbBoot,2500);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkNt()});
$('#ft').textContent='الإصدار v.05 · راجع درجة ثبوت الأحاديث من مصادرها قبل نسبتها للنبي ﷺ';
try{localStorage.setItem('adhkar.probe','1');localStorage.removeItem('adhkar.probe')}
catch(e){setTimeout(()=>toast('التخزين غير متاح — لن تُحفظ بياناتك بعد الإغلاق. استخدم النسخة الاحتياطية من الإعدادات'),1500)}
/* عمل التطبيق بدون إنترنت (Service Worker) — يعمل عند رفع الملفات على موقع https */
if('serviceWorker' in navigator&&document.querySelector('link[rel=manifest]')&&/^https?:/.test(location.protocol))
  addEventListener('load',()=>navigator.serviceWorker.register('sw.js').catch(()=>{}));
